from pathlib import Path
import sys
p=Path(sys.argv[1])
s=p.read_text(encoding='utf-8')
if 'function teacherNotesSemesterAssignment(' in s:
 print('V2.38 déjà appliquée')
 sys.exit(0)
a=s.index('let teacherNotesSelectedClass=null;')
b=s.index('\nfunction teacher(){',a)
replacement="// V2.38 — Notes par semestre, évaluations notées uniquement.\nlet teacherNotesSelectedClass=null;\nfunction teacherNotesSemesterAssignment(classId,evalId){\n const assignment=(data.teacherNotesSemesters||{})[JSON.stringify([classId,evalId])];\n return assignment===2?2:1;\n}\nfunction teacherNotesPage(allowedClassIds){\n const classes=data.classes.filter(c=>!c.archived&&allowedClassIds.includes(c.id))\n  .sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'fr'));\n if(!classes.length){shell(title('Notes','Tableau par classe')+'<div class=\"card\">Aucune classe affectée.</div>');return}\n if(!classes.some(c=>c.id===teacherNotesSelectedClass))teacherNotesSelectedClass=classes[0].id;\n const chosen=classes.find(c=>c.id===teacherNotesSelectedClass);\n const pupils=data.students.filter(st=>!st.archived&&st.classId===chosen.id)\n  .sort((a,b)=>String(a.last||'').localeCompare(String(b.last||''),'fr')||String(a.first||'').localeCompare(String(b.first||''),'fr'));\n const pupilIds=new Set(pupils.map(st=>st.id));\n const resultIds=new Set((data.results||[]).filter(r=>pupilIds.has(r.student)).map(r=>r.eval));\n const gradeIds=new Set((data.evalGrades||[]).filter(g=>pupilIds.has(g.studentId)).map(g=>g.evalId));\n const refKey=classReferentialKey(chosen);\n const candidates=data.evals.filter(ev=>evalReferentialKey(ev)===refKey&&\n   ((ev.classes||[]).includes(chosen.id)||resultIds.has(ev.id)||gradeIds.has(ev.id)))\n  .sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''),'fr')||String(a.title||'').localeCompare(String(b.title||''),'fr'));\n const valid=n=>n!==null&&n!==undefined&&Number.isFinite(Number(n));\n const grades=new Map(candidates.map(ev=>[ev.id,new Map(pupils.map(st=>[st.id,effectiveEvalGrade(ev.id,st.id)]))]));\n const assessments=candidates.filter(ev=>pupils.some(st=>valid(grades.get(ev.id).get(st.id))));\n const semester=ev=>teacherNotesSemesterAssignment(chosen.id,ev.id);\n const ordered=[...assessments.filter(ev=>semester(ev)===1),...assessments.filter(ev=>semester(ev)===2)];\n const grade=(st,ev)=>grades.get(ev.id).get(st.id);\n const cell=(st,ev)=>{\n  const value=grade(st,ev);\n  return valid(value)?'<span title=\"'+esc(evalGradeSourceLabel(ev.id,st.id))+'\">'+esc(formatGrade(value))+'</span>':'<span class=\"muted\">—</span>';\n };\n const mean=(st,sem)=>{\n  const values=assessments.filter(ev=>semester(ev)===sem).map(ev=>grade(st,ev)).filter(valid).map(Number);\n  return values.length?(values.reduce((a,b)=>a+b,0)/values.length).toLocaleString('fr-FR',{maximumFractionDigits:2})+' / 20':'—';\n };\n const headings=ordered.map(ev=>'<th style=\"min-width:155px;padding:10px;background:var(--panel);position:sticky;top:0\">'+\n  esc(ev.title||'Évaluation')+'<div class=\"muted small\">'+esc(ev.date||'')+'</div>'+\n  '<label class=\"muted small\">Semestre <select class=\"input\" style=\"padding:3px\" data-notes-semester=\"'+esc(ev.id)+'\" aria-label=\"Semestre de '+esc(ev.title||'Évaluation')+'\">'+\n  '<option value=\"1\"'+(semester(ev)===1?' selected':'')+'>1</option><option value=\"2\"'+(semester(ev)===2?' selected':'')+'>2</option></select></label></th>').join('');\n const table=assessments.length?\n  '<div style=\"overflow:auto;max-width:100%;border:1px solid var(--line);border-radius:10px\"><table style=\"width:100%;border-spacing:0;min-width:650px\"><thead><tr>'+\n  '<th style=\"position:sticky;left:0;top:0;background:var(--panel);min-width:180px;padding:10px;z-index:3\">Élève</th>'+headings+\n  '<th style=\"background:var(--panel);padding:10px\">Moy. S1</th><th style=\"background:var(--panel);padding:10px\">Moy. S2</th></tr></thead><tbody>'+\n  pupils.map(st=>'<tr><th style=\"position:sticky;left:0;background:var(--panel);text-align:left;padding:10px\">'+esc(st.last||'')+' '+esc(st.first||'')+'</th>'+\n  ordered.map(ev=>'<td style=\"text-align:center;padding:10px;border-top:1px solid var(--line)\">'+cell(st,ev)+'</td>').join('')+\n  '<td style=\"text-align:center;padding:10px;font-weight:700\">'+mean(st,1)+'</td><td style=\"text-align:center;padding:10px;font-weight:700\">'+mean(st,2)+'</td></tr>').join('')+\n  '</tbody></table></div>':\n  '<div class=\"card muted\">Aucune note pour cette classe. Les évaluations apparaîtront dès qu’un élève aura une note.</div>';\n shell(title('Notes','Récapitulatif semestriel par classe')+\n  '<div class=\"card\" style=\"margin-bottom:14px\"><label for=\"teacherNotesClass\">Classe</label> <select id=\"teacherNotesClass\" class=\"input\">'+\n  classes.map(c=>'<option value=\"'+esc(c.id)+'\"'+(c.id===chosen.id?' selected':'')+'>'+esc(c.name)+'</option>').join('')+\n  '</select><p class=\"muted small\">'+pupils.length+' élève(s) · '+assessments.length+' évaluation(s) notée(s). Choisissez le semestre sous chaque évaluation. Les notes existantes ne sont pas modifiées.</p></div>'+table);\n const select=document.getElementById('teacherNotesClass');\n if(select)select.onchange=()=>{teacherNotesSelectedClass=select.value;teacherNotesPage(allowedClassIds)};\n document.querySelectorAll('[data-notes-semester]').forEach(input=>input.onchange=()=>{\n  const evalId=input.dataset.notesSemester;\n  if(!assessments.some(ev=>ev.id===evalId))return;\n  data.teacherNotesSemesters=data.teacherNotesSemesters||{};\n  data.teacherNotesSemesters[JSON.stringify([chosen.id,evalId])]=input.value==='2'?2:1;\n  if(save()===false){alert('Impossible d’enregistrer le semestre.');return}\n  teacherNotesPage(allowedClassIds);\n });\n}\n"
s=s[:a]+replacement+s[b:]
p.write_text(s,encoding='utf-8')
print('V2.38 installé')
